//! Correctly-empty system relations: PGArbor v1 cannot create the objects they would list
//! (triggers, policies, publications, foreign servers, large objects, security labels, ...) or
//! collects no such state (planner statistics, replication, progress reporting), so zero rows IS the
//! PostgreSQL answer for a database in that state. Each entry carries its justification; the list is
//! generated by `gen/classify_vrel.py`. When a feature is implemented later its relation moves out of
//! this list into a producer file. Fully implemented, frozen (v1).
use super::{Row, ScanContext, ScanRequest, VirtualRelation};
use crate::builtin::relid;
use pgarbor_common::{Oid, Result};


/// A system relation that has no rows.
// CONTRACT
#[derive(Clone, Copy, Debug)]
pub struct EmptyRelation(pub Oid);

impl VirtualRelation for EmptyRelation {
    fn oid(&self) -> Oid {
        self.0
    }
    fn scan(&self, _ctx: &ScanContext, _req: &ScanRequest) -> Result<Vec<Row>> {
        Ok(Vec::new())
    }
}

include!("empty_list.inc");
